const row = items[0]?.json ?? {};

const phoneNumber = String(row.phone_number || '').trim();
const instanceName = String(row.instance_name || $env.EVOLUTION_DEFAULT_INSTANCE || '').trim();
const messageText = String(row.response_text || row.text_body || '').trim();
const conversationId = row.conversation_id ?? null;
const leadId = row.lead_id ?? null;
const responseKind = row.response_kind || 'system_message';
const apiBaseUrl = String($env.EVOLUTION_API_BASE_URL || '').replace(/\/$/, '');
const apiKey = String($env.EVOLUTION_API_KEY || '').trim();

if (!conversationId) {
  throw new Error('WA - Outbound Messages requiere conversation_id');
}

if (!phoneNumber) {
  throw new Error('WA - Outbound Messages requiere phone_number');
}

if (!messageText) {
  throw new Error('WA - Outbound Messages requiere response_text o text_body');
}

if (!instanceName) {
  throw new Error('WA - Outbound Messages requiere instance_name o EVOLUTION_DEFAULT_INSTANCE');
}

if (!apiBaseUrl || !apiKey) {
  throw new Error('Evolution API no esta configurada en variables de entorno');
}

const stableHash = (value) => {
  let hash = 2166136261;
  for (const char of String(value || '')) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16);
};
const triggerKey = row.message_id || row.external_message_id || `text:${stableHash(messageText)}`;
const idempotencyKey = row.delivery_key
  || row.idempotency_key
  || `evolution:${instanceName}:${conversationId}:${triggerKey}:${responseKind}`;

const outboundBody = {
  number: phoneNumber,
  text: messageText,
  delay: 0,
  linkPreview: false,
};

return [
  {
    json: {
      conversation_id: conversationId,
      lead_id: leadId,
      phone_number: phoneNumber,
      instance_name: instanceName,
      message_type: 'text',
      text_body: messageText,
      response_kind: responseKind,
      outbound_url: `${apiBaseUrl}/message/sendText/${encodeURIComponent(instanceName)}`,
      outbound_body: outboundBody,
      raw_payload_json: JSON.stringify(outboundBody),
      outbound_claim_stale_seconds: Math.max(30, Number($env.OUTBOUND_CLAIM_STALE_SECONDS || 300)),
      idempotency_key: idempotencyKey,
    },
  },
];

const retryableStatusCodes = new Set([408, 409, 425, 429, 500, 502, 503, 504]);
// Evolution does not expose a request idempotency key. Retrying a POST after an
// ambiguous timeout can duplicate a WhatsApp message, so each claimed operation
// is sent at most once and ambiguous results are reconciled operationally.
const maxAttempts = 1;
const baseDelayMs = Number($env.EXTERNAL_HTTP_RETRY_BASE_MS || 1000);
const maxDelayMs = Number($env.EXTERNAL_HTTP_RETRY_MAX_MS || 10000);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const retryDelay = (attempt) => {
  const exponential = Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt - 1));
  const jitter = Math.floor(Math.random() * 250);
  return exponential + jitter;
};

const normalizeBody = (value) => {
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (_error) {
      return { raw: value };
    }
  }
  return value || {};
};

const row = items[0]?.json ?? {};
const instanceName = String(row.instance_name || $env.EVOLUTION_DEFAULT_INSTANCE || '').trim();
const apiBaseUrl = String($env.EVOLUTION_API_BASE_URL || '').replace(/\/$/, '');
const url = String(row.outbound_url || (apiBaseUrl && instanceName ? `${apiBaseUrl}/message/sendText/${encodeURIComponent(instanceName)}` : '')).trim();
const body = row.outbound_body || row.raw_payload;

if (row.already_sent === true || row.should_send === false) {
  return [];
}

if (!url) throw new Error('Send Evolution Message requiere outbound_url');
if (!body) throw new Error('Send Evolution Message requiere outbound_body');

let lastError = null;

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    const response = await helpers.httpRequest({
      method: 'POST',
      url,
      headers: {
        apikey: $env.EVOLUTION_API_KEY,
        'Content-Type': 'application/json',
      },
      body,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });

    const statusCode = Number(response.statusCode || 0);
    const shouldRetry = retryableStatusCodes.has(statusCode) && attempt < maxAttempts;
    if (!shouldRetry) {
      return [
        {
          json: {
            ...row,
            statusCode,
            body: normalizeBody(response.body),
            headers: response.headers || {},
            retry_attempts: attempt,
            retry_exhausted: retryableStatusCodes.has(statusCode) && attempt >= maxAttempts,
            retry_last_error: null,
          },
        },
      ];
    }
  } catch (error) {
    lastError = error;
    if (attempt >= maxAttempts) {
      return [
        {
          json: {
            ...row,
            statusCode: 0,
            body: { message: error.message },
            headers: {},
            retry_attempts: attempt,
            retry_exhausted: true,
            retry_last_error: error.message,
          },
        },
      ];
    }
  }

  await sleep(retryDelay(attempt));
}

return [{ json: { ...row, statusCode: 0, body: { message: lastError?.message || 'HTTP retry exhausted' }, headers: {}, retry_attempts: maxAttempts, retry_exhausted: true, retry_last_error: lastError?.message || null } }];

const row = items[0]?.json ?? {};

const statusCode = Number(row.statusCode_2 || row.statusCode || 0);
const responseBody = row.body_2 || row.body || {};
const retryAttempts = Number(row.retry_attempts_2 || row.retry_attempts || 1);
const retryExhausted = Boolean(row.retry_exhausted_2 || row.retry_exhausted || false);
const retryLastError = row.retry_last_error_2 || row.retry_last_error || null;
const messageId = row.id_1 || row.id || null;
const conversationId = row.conversation_id_1 || row.conversation_id || null;
const leadId = row.lead_id_1 || row.lead_id || null;
const responseKind = row.response_kind_1 || row.response_kind || 'system_message';
const externalMessageId = responseBody?.key?.id || responseBody?.data?.key?.id || null;
const rawPayload = row.raw_payload_1 || row.raw_payload || {};
const isV3Delivery = ['validated_conversation_decision/v3', 'system_contingency_decision/v3']
  .includes(rawPayload?.version);
const deliveryStatus = statusCode >= 200 && statusCode < 300
  ? 'sent'
  : (statusCode === 0 || statusCode >= 500 ? 'unknown' : 'failed');
const dispatchPhase = deliveryStatus;
const reconciliationRequired = deliveryStatus === 'unknown'
  || (isV3Delivery && deliveryStatus === 'failed');
const reconciliationReason = reconciliationRequired
  ? (retryLastError || `ambiguous_provider_outcome_status_${statusCode}`)
  : null;

return [
  {
    json: {
      message_id: messageId,
      conversation_id: conversationId,
      lead_id: leadId,
      delivery_status: deliveryStatus,
      dispatch_phase: dispatchPhase,
      reconciliation_required: reconciliationRequired,
      reconciliation_reason: reconciliationReason,
      external_message_id: externalMessageId,
      event_name: 'evolution_outbound_delivery',
      result: deliveryStatus,
      after_payload_json: JSON.stringify({
        status_code: statusCode,
        response_body: responseBody,
        retry_attempts: retryAttempts,
        retry_exhausted: retryExhausted,
        retry_last_error: retryLastError,
      }),
      metadata_json: JSON.stringify({
        response_kind: responseKind,
        provider: 'evolution_api',
        retry_attempts: retryAttempts,
        retry_exhausted: retryExhausted,
      }),
    },
  },
];

return items.map((item) => ({ json: {
  ...item.json,
  delivery_key: item.json.delivery_key || item.json.idempotency_key || null,
  provider_external_message_id: item.json.provider_external_message_id
    || item.json.external_message_id
    || null,
  outbound_dispatch_status: item.json.already_sent === true ? 'already_sent' : 'not_dispatched',
} }));
